<template>
  <div class="shop-page">
    <!-- Carousel -->
    <div class="carousel">
      <img :src="carouselImages[currentSlide]" alt="SapaShoes banner" />
      <button class="nav prev" @click="prevSlide">‹</button>
      <button class="nav next" @click="nextSlide">›</button>
    </div>

    <!-- Products -->
    <section class="products">
      <h2>Featured Shoes</h2>
      <div class="product-grid">
        <div class="product-card" v-for="shoe in shoes" :key="shoe.id">
          <img :src="shoe.image" :alt="shoe.name" />
          <p class="shoe-name">{{ shoe.name }}</p>
        </div>
      </div>
    </section>
  </div>
</template>

<script>
  import banner1 from '@/assets/carousel/banner1.jpg'
  import banner2 from '@/assets/carousel/banner2.jpg'
  import banner3 from '@/assets/carousel/banner3.jpg'
  
  import shoes1 from '@/assets/shoes/shoes1.jpg'
  import shoes2 from '@/assets/shoes/shoes2.jpg'
  import shoes3 from '@/assets/shoes/shoes3.jpg'
  import shoes4 from '@/assets/shoes/shoes4.jpg'
  import shoes5 from '@/assets/shoes/shoes5.jpg'
  import shoes6 from '@/assets/shoes/shoes6.jpg'
  import shoes7 from '@/assets/shoes/shoes7.jpg'
  import shoes8 from '@/assets/shoes/shoes8.jpg'

export default {
  name: 'SapaShoes',
  data() {
    return {
      currentSlide: 0,
      carouselImages: [banner1, banner2, banner3],
      shoes: [shoes1, shoes2, shoes3, shoes4, shoes5, shoes6, shoes7, shoes8],
      shoes: [
        { id: 1, name: 'Air Runner', image: shoes1 },
        { id: 2, name: 'Street Flex', image: shoes2 },
        { id: 3, name: 'Urban Pro', image: shoes3 },
        { id: 4, name: 'Classic Walk', image: shoes4 },
        { id: 5, name: 'Sport Max', image: shoes5 },
        { id: 6, name: 'Cloud Step', image: shoes6 },
        { id: 7, name: 'Night Runner', image: shoes7 },
        { id: 8, name: 'Daily Comfort', image: shoes8 }
      ]
    }
  },
  methods: {
    nextSlide() {
      this.currentSlide =
        (this.currentSlide + 1) % this.carouselImages.length
    },
    prevSlide() {
      this.currentSlide =
        (this.currentSlide - 1 + this.carouselImages.length) %
        this.carouselImages.length
    }
  }
}
</script>

<style scoped>
.shop-page {
  width: 100%;
  font-family: system-ui, sans-serif;
}

/* Carousel */
.carousel {
  position: relative;
  width: 100%;
  height: 500px;
  overflow: hidden;
}

.carousel img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.nav {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0, 0, 0, 0.5);
  color: white;
  border: none;
  font-size: 2rem;
  padding: 0.5rem 1rem;
  cursor: pointer;
}

.prev {
  left: 20px;
}

.next {
  right: 20px;
}

/* Products */
.products {
  padding: 4rem 2rem;
  max-width: 1400px;
  margin: 0 auto;
}

.products h2 {
  text-align: center;
  font-size: 2.5rem;
  margin-bottom: 3rem;
  color: #111827;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
}

.product-card {
  background: #ffffff;
  border-radius: 12px;
  padding: 1.5rem;
  text-align: center;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.08);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.product-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.12);
}

.product-card img {
  width: 100%;
  border-radius: 8px;
  margin-bottom: 1rem;
}

.shoe-name {
  font-size: 1.1rem;
  font-weight: 600;
  color: #1f2933;
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
}
</style>
